// MAY IMPORT: `option`, `addr`, `sys` and `core` (`meta/specs/BUILD.md` B-18's table).
use "./socket.npk".*;

mod:core;

error:ECore;

pub func:core_f = int64(int64:n) {
    if (n > 1i64) { fail ECore; }
    pass n;
};

mod:sys;

pub func:sys_pid = int64() {
    Result<int64>:r = sys(39i64);
    if (r.is_error) { pass 0i64; }
    pass r.value;
};

mod:sys;

pub fixed int64:SYS_SENDTO = 44i64;

pub func:sys_send = int64(int64:d, int64:p, int64:n) {
    Result<int64>:r = sys(SYS_SENDTO, d, p, n, 0i64, 0i64, 0i64);
    if (r.is_error) { pass 0i64; }
    pass r.value;
};

mod:core;

pub func:core_put<T> = int64(T:x) {
    wild int8->:none = calloc(1i64, 8i64);
    Result<int64>:r = write((1i32) =>! fd, none, 0i64);
    dalloc(none);
    if (r.is_error) { pass 0i64; }
    pass r.value;
};

mod:sys;

pub fixed int64:SYS_SETSOCKOPT = 54i64;

pub func:sys_opt = int64(int64:d) {
    Result<int64>:r = sys(SYS_SETSOCKOPT, d, 1i64, 2i64, 0i64, 0i64);
    if (r.is_error) { pass 0i64; }
    pass r.value;
};
